import { ethers } from "hardhat";
import { abi as pairABI } from "@uniswap/v2-core/build/IUniswapV2Pair.json";
import { abi as poolABI } from "@uniswap/v3-core/artifacts/contracts/interfaces/IUniswapV3Pool.sol/IUniswapV3Pool.json";
import { abi as erc20ABI } from "@openzeppelin/contracts/build/contracts/IERC20.json";
import { BytesLike } from "ethers";

(async function () {
    const v2Interface = new ethers.utils.Interface(pairABI);
    const v3Interface = new ethers.utils.Interface(poolABI);
    const decodedDataFor4Swap = v2Interface.decodeFunctionData(
        "swap",
        ""
    );
    console.log(decodedDataFor4Swap);
    const decodedCallDataFor4Swap = ethers.utils.defaultAbiCoder.decode(
        ["address", "bytes"],
        decodedDataFor4Swap[3]
    );
    console.log(decodedCallDataFor4Swap);

    const decodedDataFor3Swap = v2Interface.decodeFunctionData(
        "swap",
        decodedCallDataFor4Swap[1]
    );
    console.log(decodedDataFor3Swap);
    const decodedCallDataFor3Swap = ethers.utils.defaultAbiCoder.decode(
        ["address", "bytes"],
        decodedDataFor3Swap[3]
    );
    console.log(decodedCallDataFor3Swap);

    const decodedDataFor2Swap = v2Interface.decodeFunctionData(
        "swap",
        decodedCallDataFor3Swap[1]
    );
    console.log(decodedDataFor2Swap);
    const decodedCallDataFor2Swap = ethers.utils.defaultAbiCoder.decode(
        ["address", "bytes"],
        decodedDataFor2Swap[3]
    );
    console.log(decodedCallDataFor2Swap);

    const decodedDataFor1Swap = v3Interface.decodeFunctionData(
        "swap",
        decodedCallDataFor2Swap[1]
    );
    console.log(decodedDataFor1Swap);
    const decodedCallDataFor1Swap = ethers.utils.defaultAbiCoder.decode(
        ["address", "bytes"],
        decodedDataFor1Swap[4]
    );
    console.log(decodedCallDataFor1Swap);

    const ercInterface = new ethers.utils.Interface(erc20ABI);
    const decodedInitialTransfer = ercInterface.decodeFunctionData(
        "transfer",
        decodedCallDataFor1Swap[1]
    );
    console.log(decodedInitialTransfer);
    // const decodedCallDataForInitialTransfer =
    //     ethers.utils.defaultAbiCoder.decode(
    //         ["address", "uint"],
    //         decodedInitialTransfer[3]
    //     );
    // console.log(decodedCallDataForInitialTransfer);
})();
